(()=>{"use strict";class t{constructor(t){this.container=t,this.button=t.querySelector(".collapse-btn"),this.body=t.querySelector(".collapse-body"),this.isOpen=!1,this.init()}init(){this.button.addEventListener("click",this.toggle.bind(this))}toggle(){if(this.isOpen=!this.isOpen,this.body.classList.toggle("open"),this.isOpen){const t=this.body.scrollHeight;this.body.style.maxHeight=t+"px"}else this.body.style.maxHeight="0px"}}document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll(".collapse-wrapper").forEach((e,s)=>{const i=e.querySelector(".collapse-body");i.id||(i.id=`collapse${s+1}`),new t(e)})})})();